// TH18 v1.00a Stage 5 道中 MainSub06 (st05.ecl.txt:1159-1176).
// GirlD02 body: st05.ecl.txt:681-704; GirlD02_at: st05.ecl.txt:706-752.
// Source t0 = target frame 120 (120-frame practice buffer).
const TIME_LIMIT: int = 1500;   // 120 buffer + source motion/fire + trailing shots
const TH18_STAR_R: int = 608;   // source type16, radius 4
const TH18_STAR_L: int = 944;   // source type37, radius 4
const D02_STEP: int = 1092;     // source %F0 +/-0.10472 rad = +/-6deg
const D02_SPEED0: fx = 0.6fx;   // source etSpeed s0; etCount layer=1 so s1 unused

// Bullet EX (GirlD02_at): ANIM(1) birth retreat already folded into the spawn
// offset below (etDist 16 - 4*0.6 = 13.6px), WAIT(60), then VELTIME(60) ramps
// the scalar speed 0.6 -> 2.0/2.0/2.2/2.5 along the launch angle.
xformdef D02_RAMP(target: fx) {
    @60 add_speed(0fx);
ramp:
    add_speed((target - D02_SPEED0) / 60fx);
    wait(1);
    loop(ramp, 60);
}

// One %RANDRAD base, then 140 fixed-direction rings every 4 frames.
// etAim 3: angle = base + 2*pi*i/N; the etAngle delta 40deg only scales layer
// q, and etCount layer M=1, so it never affects a bullet.
async sub girl_fire(dir: int, shape: int) {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var n: int = 1;          // etCount: E1 / N4 / H5 / L6
    var target: fx = 2.0fx;  // VELTIME r: E/N 2.0, H 2.2, L 2.5
    if rank == 1 { n = 4; }
    if rank == 2 { n = 5; target = 2.2fx; }
    if rank == 3 { n = 6; target = 2.5fx; }
    var base: int = rand(65536) - 32768; // %RANDRAD, drawn once before first shot
    for shot in 0..140 {
        for i in 0..n {
            var a: angle = (base + (i * 65536) / n) as angle;
            _ = fire(shape, 6, $self_x + 13.6fx * cos(a), $self_y + 13.6fx * sin(a),
                     D02_SPEED0, a, D02_RAMP(target), none);
        }
        wait(4);
        var step: int = D02_STEP; // Easy executes %A = %A + %F0 twice per shot
        if rank == 0 { step = D02_STEP * 2; }
        base = base + step;
        if base > 32767 { base = base - 65536; }
        if base < -32768 { base = base + 65536; }
    }
}

// GirlD02: source setHurtbox(32,32)->16, setHitbox(24,24)->12.
// moveVel(90deg,3) then moveVelTime(60,mode1=t^2,90deg,0); after 500 frames
// moveSpeedTime(120,mode1,2) and hold.
async sub girl(dir: int, shape: int) {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn girl_fire(dir, shape);
    wait(500);
    move_speed(120, 2fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1000); }
}

// MainSub06: parent stage is at (0,0); %F0/$I0 are passed as task args.
async sub wave() {
    wait(120);
    _ = spawn_enemy(128fx, -48fx, 4000, 0, 0, 0, girl(D02_STEP, TH18_STAR_R));
    _ = spawn_enemy(-128fx, -48fx, 4000, 0, 0, 0, girl(-D02_STEP, TH18_STAR_L));
    wait(400);
    _ = spawn_enemy(64fx, -48fx, 4000, 0, 0, 0, girl(-D02_STEP, TH18_STAR_L));
    _ = spawn_enemy(-64fx, -48fx, 4000, 0, 0, 0, girl(D02_STEP, TH18_STAR_R));
    wait(400);
}

// Practice shell: control enemy at (0,0), no body collision; real GirlD02
// enemies keep their source hit/hurt boxes (and are invulnerable as usual).
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 100000, 0, 0, 0, control);
    loop { wait(600); }
}
